# 테스트
@Test
void conversionService() {
    DefaultConversionService service = new DefaultConversionService();
    service.addConverter(new StringToIpPortConverter());

    IpPort result = service.convert("127.0.0.1:8080", IpPort.class);
    // IpPort(ip=127.0.0.1, port=8080)

    String s = service.convert(new IpPort("127.0.0.1", 8080), String.class);
    // "127.0.0.1:8080"  <- 이건 아직 안 된다
}

# ConverterNotFoundException:
# No converter found capable of converting from type [IpPort] to type [String]

